widget.draw:
function draw(ctx, state, t) {
  var w = state.w;
  var h = state.h;
  var pos = state.pos;
  var ii = state.i;
  var d = state.d;
  function fmt(v) { return Math.round(v * 100) / 100; }
  function denom() { return Math.pow(10000, (2 * ii) / d); }
  function encf(p) { return Math.sin(p / denom()); }
  function X(p) { return 50 + p / 20 * 480; }
  function Y(v) { return 150 - v * 90; }
  var angle = pos / denom();
  var enc = Math.sin(angle);
  var k = 0;
  var p = 0;
  var y = 0;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#d8cfbf";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(50, Y(0));
  ctx.lineTo(530, Y(0));
  ctx.stroke();
  ctx.strokeStyle = "#1d1a16";
  ctx.lineWidth = 1;
  ctx.strokeRect(50, 50, 480, 200);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (k = 0; k <= 120; k++) {
    p = k / 120 * 20;
    y = encf(p);
    if (k === 0) { ctx.moveTo(X(p), Y(y)); } else { ctx.lineTo(X(p), Y(y)); }
  }
  ctx.stroke();
  ctx.strokeStyle = "#8a8175";
  ctx.lineWidth = 1;
  ctx.beginPath();
  y = 50;
  while (y < 250) {
    ctx.moveTo(X(pos), y);
    ctx.lineTo(X(pos), y + 5);
    y = y + 10;
  }
  ctx.stroke();
  var q = 0;
  var qy = 0;
  for (k = -1; k <= 1; k++) {
    q = pos + k;
    if (q >= 0) {
      if (q <= 20) {
        qy = encf(q);
        ctx.fillStyle = "#c4512c";
        if (k === 0) { ctx.fillStyle = "#1f4b99"; } else { ctx.fillStyle = "#c4512c"; }
        ctx.beginPath();
        ctx.arc(X(q), Y(qy), 6, 0, 6.2832);
        ctx.fill();
      }
    }
  }
  ctx.fillStyle = "#1d1a16";
  ctx.font = "13px sans-serif";
  ctx.fillText("angle = " + fmt(angle), 50, 292);
  ctx.fillText("enc = " + fmt(enc), 260, 292);
  ctx.fillText("pos = " + fmt(pos), 50, 314);
  ctx.fillText("enc(pos-1) to enc(pos+1) stay close", 260, 314);
  ctx.font = "12px sans-serif";
  ctx.fillStyle = "#8a8175";
  ctx.fillText("sin(pos / 10000 to power 2i over d)", 50, 30);
  ctx.fillText("pos 0 to 20", 50, 268);
}
